import { Component, OnInit } from '@angular/core';
import { CountriesService, Country } from './countries.service';
import { FormControl, Validators } from '@angular/forms';
import { combineLatest, map, Observable, startWith } from 'rxjs';

@Component({
  selector: 'app-exercise1',
  templateUrl: './exercise1.component.html',
  styleUrls: ['./exercise1.component.css'],
})
export class Exercise1Component implements OnInit {
  countries$ = this.countriesService.getCountries();
  countriesControl = new FormControl<Country['id']>('select coutry',
    {validators: Validators.required,
      nonNullable: true,
    }
  )

  currentCountry$ = combineLatest([
    this.countries$,
    this.countriesControl.valueChanges.pipe(startWith(this.countriesControl.value))
  ])
  .pipe(
    map(([country, countryID]) => {
      console.log(country);
      console.log(countryID);
      return country.find((c) => c.id === countryID)?.id;
  })) ;

  constructor(private countriesService: CountriesService) {}

  ngOnInit() {}

  trackByCountryId(index: number, country: Country) {
    return country.id;
  }

}
<h2>Exercise 1</h2>
<h3>Your mission is to turn the following dropdown into a country-selection dropdown.</h3>
<img src="assets/exercise1.gif" />
<ol>
  <li>Open a terminal in your project <code>ng-advanced-workshop</code></li>
  <li>Run <code>npm run server</code> to start the sample back-end that holds the data needed for all exercises</li>
  <li>
    Update the code in <code>app/exercise1</code> so that our component loads its list of countries from
    <code>http://localhost:3000/countries</code>
  </li>
  <li>Display the total number of countries in the corresponding <code>div</code></li>
  <li>Selecting a country should result in the <code>id</code> of the country being set as the dropdown value</li>
</ol>
<h4>
  You can take a look at the expected result here: <a routerLink="/solution/1">http://localhost:4200/solution/1</a>
</h4>
<hr />
<h2>Result</h2>

<!-- Edit the code down below to implement the requested features -->
<ng-container *ngIf='countries$ | async as countries'>
  <div>Select one of {{countries.length}} countries:</div>
  <ng-container *ngIf="countries.length > 0">
    <select [formControl]="countriesControl">
      <option disabled [value]="'select coutry'">--Select the country--</option>
      <option *ngFor="let country of countries; trackBy: trackByCountryId" [value]="country.id">
        {{country.description}}
      </option>
    </select>
  </ng-container>
  <div>Current value: {{countriesControl.value}}</div>
  <div>Current value: {{currentCountry$ | async }}</div>
</ng-container>
